sub save_password_policy {
    my $c    = shift;   
    $cdb = esmith::ConfigDB::UTF8->open()   || die("Couldn't open config db");
    $cdb->reload();
    my $key = $cdb->get('passwordstrength');
    return $c->l('pdo_CANNOT_SAVE_DB') unless $key;
    $c->app->log->info("got here!!!!!");
    eval {
		$c->app->log->info("and here (1)!!!!!");
        $key->set_prop('Admin',  $c->param('Admin'));
        $key->set_prop('Ibays',  $c->param('Ibays'));
        $key->set_prop('Users',  $c->param('Users'));
        $key->set_prop('length',  $c->param('passwordlength'));

        $key = $cdb->get('passwordaging');
        if (!$key) {
            $cdb->set_value('passwordaging', 'configuration');
            $key = $cdb->get('passwordaging');
            die "passwordaging missing after create" unless $key;
        }
		$c->app->log->info("and here (2)!!!!!");

        $key->set_prop('Active',      $c->param('Active'));
        $key->set_prop('PwdAge',      $c->param('PwdAge'));
        $key->set_prop('PwdWarn',     $c->param('PwdWarn'));
        $key->set_prop('LockAccount',  $c->param('LockAccount'));
        $key->set_prop('DateReset',    $c->param('DateReset'));
        $cdb->set_value('passwordhistory', $c->param('passwordhistory'));
		$c->app->log->info("and here (3)!!!!!");
    } or do {
		$c->app->log->error("save_password_policy failed: $@");
		return $c->l('pdo_cannot_save_db') unless $key;
    };

    my $rc = system('/sbin/e-smith/expand-template', '/etc/pam.d/system-auth');
    return $c->l('pdo_template_expand_failed') if $rc != 0;

    my $ret = $c->modify_password_age_for_users();
    $ret = 'ok' if !defined($ret) || $ret eq '';
    return $ret;
}

