sub get_users_table
{
	my $c = shift;
	my @data = ();
	$adb = esmith::AccountsDB::UTF8->open() || die("Couldn't open Accounts db");
	for my $user ($adb->users)
		{
		my $passset = $user->prop('PasswordSet') || 'no';
		my $star = '';
		if ( $passset eq 'no' ) {
			$star = $c->l('ACCOUNT_LOCKED');
		}
		my $key = $user->key;
        my $expiration = decode('UTF-8',`chage -l "$key" 2>/dev/null | grep 'Password expires' | cut -d ':' -f 2`);
        my $lastchange = decode('UTF-8',`chage -l "$key" 2>/dev/null | grep -i 'last' | cut -d ':' -f 2`);

        my $passage = $user->prop('PasswordAge') || 'no';
        my $checked = ($passage eq 'yes') ? ' checked' : '';
        my $checkbox = $key . $checked;
		push @data,
		{
			User => $user->key,
			FullName => $user->prop('FirstName') . " " . $user->prop('LastName') ,
			Passwordaging => $c->l($passage) ,
			Lastchange => $lastchange ,
			Passwordexpire => $expiration ,
            EnableAgeingValue  => $key,
            EnableAgeingChecked => $checked,
			Note => $star
			}
		}
	return @data
	}

sub modify_password_age_for_users {
    my $c = shift;
    $adb = esmith::AccountsDB::UTF8->open() || die("Couldn't open Accounts db");
    $adb->reload();
    my $ret = '';
    my @acctName;

    # All checked checkbox values named PasswordAge
    my $cusers = $c->every_param('Table1_EnableAgeing') || [];
	$c->app->log->info("Found " . scalar(@$cusers) . " PasswordAge entries");
    
    # Clear the setting for all users first
    for my $user ($adb->users) {
        #next unless (($user->prop('PasswordSet') || 'no') eq 'yes'); #Do it for all inc locked ones
        $user->set_prop('PasswordAge', 'no');
        push @acctName, $user->key;
    }

    # Re-apply only for checked users
    for my $m (@$cusers) {
        my $key = $adb->get($m);      
        next unless $key;
        $key->set_prop('PasswordAge', 'yes');
    }

    if (system('/sbin/e-smith/signal-event', 'password-modify', @acctName) != 0) {
        $ret = $c->l('pdo_signal_failed');
    }

    return $ret;
}  
